mapper.select:
select p.*,s.name as species_val,s.name_en as species_val_en,o.organization_name,u.user_name,i.indicator_name,i.indicator_name_en,ps.name as ps_name,ps.name_en as ps_name_en from tb_project p left join tb_project_member m on p.project_id = m.project_id left join tb_species s on p.species_id = s.species_id left join sys_organization o on p.organization_id = o.organization_id left join sys_user u on p.create_by = u.user_id left join tb_pathological_indicator i on p.tag_id = i.indicator_id left join tb_product_series ps on p.product_series_id = ps.product_series_id
p.status != '1'
AND m.user_id = #{params.userId}
AND p.project_name like CONCAT('%',#{params.projectName},'%')
AND p.product_series_id = #{params.productSeriesId}
AND p.species_id = #{params.speciesId}
AND p.project_type = #{params.projectType}
AND p.project_type in ('1','3')
AND p.create_by = #{params.createBy}
AND u.user_name like CONCAT('%',#{params.userName},'%')
AND p.status = #{params.status}
AND p.color_type = #{params.colorType}
and date_format(m.create_time,'%y%m%d') >= date_format(#{params.createTimeParams.beginTime},'%y%m%d')
and date_format(m.create_time,'%y%m%d') <= date_format(#{params.createTimeParams.endTime},'%y%m%d')
order by p.create_time desc

